"""Lesson-specific pages, source-linked workflow and reproducible README."""
STYLE+='''
body{overflow-wrap:anywhere}.control-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}select,input{font:700 20px/1.5 "Segoe UI",Arial;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--paper);color:var(--ink);width:100%}input[type=checkbox]{width:25px;height:25px;vertical-align:middle}.workspace{margin:24px 0}.json-view{max-height:530px}.markdown-body{white-space:normal!important}.markdown-body li{margin:12px 0}.stats{grid-template-columns:repeat(3,minmax(0,1fr))}.table{max-width:100%}#notice:empty{display:none}.workflow-step{scroll-margin-top:20px}@media(max-width:850px){.control-grid,.stats{grid-template-columns:1fr}}'''
(PUBLIC/'style.css').write_text(STYLE,encoding='utf-8')
learn=[('Select a model','Compare the same small task with pinned Haiku, Sonnet and Opus IDs. Inspect the model on actual assistant messages. Aliases can move over time; account and provider access differ.'),('Configure a backup honestly','Pass a distinct fallbackModel and inspect the option. A healthy request does not demonstrate overload, fallback activation or a return to the primary.'),('Separate effort and thinking','Use supported effort levels separately from adaptive or disabled thinking. This lab omits thinking text and counts only returned thinking blocks. A zero count does not prove that no internal reasoning happened.'),('Preserve the subprocess environment','Spread process.env in TypeScript, then add a harmless classroom value. Observe that value and cwd from an actual guarded Node command without displaying keys.'),('Choose the correct project','Start a new query in Alpha or Beta. Confirm its marker and actual process cwd. Additional directories grant file access, not configuration loading.'),('Compare observations','Record actual cost estimates, elapsed time, model IDs and results. One small sample is a classroom observation, not a model-quality or speed benchmark.')]
models=['claude-haiku-4-5-20251001','claude-sonnet-4-6','claude-opus-4-6']
options=''.join(f'<option value="{m}"'+(' selected' if 'sonnet' in m else '')+'>'+m+'</option>' for m in models)
body='''<div class="flow"><div><b>01 · Select</b><p>Model, effort and thinking</p></div><span>→</span><div><b>02 · Configure</b><p>Environment and project</p></div><span>→</span><div><b>03 · Observe</b><p>Real tool and model evidence</p></div></div><section class="panel" id="controls"><h2>Where and how will this agent run?</h2><p class="meta" id="configuration">Checking server configuration…</p><div class="control-grid"><div><label for="model">Pinned model</label><select id="model">'''+options+'''</select></div><div><label for="effort">Requested effort</label><select id="effort"><option>low</option><option>medium</option><option>high</option></select></div><div><label for="thinking">Thinking configuration</label><select id="thinking"><option>adaptive</option><option>disabled</option></select></div><div><label for="project">Working directory</label><select id="project"><option value="alpha">Alpha project</option><option value="beta">Beta project</option></select></div><div><label for="fallback">Optional backup</label><select id="fallback"><option value="">None</option>'''+''.join(f'<option>{m}</option>' for m in models)+'''</select></div><div><label for="shared"><input type="checkbox" id="shared"> Enable shared reference</label></div></div><p class="note">Fixed task: read notes.md, run the exact harmless context probe, and report the project marker, environment value and two TODOs. With shared access enabled, also read reference.md. No edits or arbitrary commands.</p><button class="primary" id="run" disabled>Run the configuration experiment →</button><p class="meta">The pinned Haiku 4.5 example requires disabled thinking and omits effort. Sonnet and Opus support the lab’s adaptive examples. No claim is made that all models support every effort or thinking combination.</p></section>
<div class="workspace"><section class="panel" id="outcome"><div class="eyebrow">ACTUAL SDK RESULT</div><h2 id="status" aria-live="polite">Ready</h2><div class="stats"><div class="stat"><span>SDK turns</span><strong id="turns">—</strong></div><div class="stat"><span>Estimated cost</span><strong id="cost">—</strong></div><div class="stat"><span>Observed elapsed time</span><strong id="duration">—</strong></div></div><p>Actual assistant model: <strong id="actual-model">—</strong></p><p class="meta">Session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p class="note" id="notice"></p></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><p class="meta">Safe projection. Raw environment values, credentials and absolute private paths are excluded.</p><pre class="json-view"><code class="language-json" id="options">{ "state": "Waiting for a run" }</code></pre></section></div>
<section class="step" id="environment-panel"><h2>Actual subprocess environment and cwd</h2><p id="probe-status">Waiting for actual tool output</p><pre><code id="probe" class="language-json">{ "state": "No tool evidence yet" }</code></pre><p class="meta">PostToolUse reads the real exact-command output, validates the harmless classroom variable and compares the observed cwd with the selected project. This is separate from the model’s answer. The full environment is never printed.</p></section>
<section class="step" id="model-panel"><h2>Requested model versus observed model</h2><pre class="json-view"><code id="init" class="language-json">{ "state": "Waiting for system/init" }</code></pre><p id="fallback-status">No fallback evidence has been observed.</p><p>Returned thinking blocks: <strong id="thinking-count">0</strong>. Thinking text is omitted and never displayed.</p><p class="meta">Effort controls reasoning allocation on supported models. Thinking configures extended thinking; display controls returned text where supported. These are independent settings with model-specific constraints. No thinking text is needed to complete this lab.</p></section>
<section class="step" id="event-panel"><h2>Actual SDK messages and tool requests</h2><ul id="events"></ul></section><section class="step" id="run-history"><h2>Compare your observations</h2><div class="table"><table><thead><tr><th>Requested model</th><th>Project</th><th>Requested effort / thinking</th><th>Observed model</th><th>Result</th><th>Estimate</th><th>Time</th></tr></thead><tbody id="history"></tbody></table></div><p class="meta">The effective options panel records when effort is omitted. Repeat matched tasks before making comparisons; one run does not establish model quality or guaranteed speed.</p></section><section class="note"><h3>Scope of the experiment</h3><p>Real SDK queries demonstrate pinned models, supported effort/thinking configurations, subprocess environment inheritance, separate cwd values and an extra shared-directory read. Fallback is configured but no provider outage is manufactured. Alias tables, fallback chains, summarized thinking, fixed thinking budgets and Python mappings are reference material. Filesystem settings are disabled explicitly. Application guards are not an operating-system sandbox. The SDK cost threshold is not an exact billing guarantee.</p></section><button id="download">Download actual observations</button>'''
document('/','Select a model. <em>Observe its context.</em>','Tune supported reasoning settings, preserve the environment and verify where the agent actually works.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you will <em>learn.</em>','The lesson’s model, effort, thinking, environment and directory concepts become visible experiments.',cards(learn)+actions(('/run.html','Configure and run →'),('/architecture.html','Architecture →')))
setup='cd .\\agent-sdk\\lesson10-models-environment\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n# http://127.0.0.1:3110'
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3110'
runsteps=[('Check prerequisites','Use Node.js 24+, npm, an Anthropic key and access to the model you select. Keep optional npm dependencies enabled. Python is not needed to run this TypeScript app.',''),('Install, configure and start','From presentations, run these commands. Preserve an existing .env. Enter your own key locally; never commit the real file. npm start explicitly loads the optional file. Shell variables take precedence.',snippet(setup,'powershell')+snippet(env,'dotenv')),('Run Sonnet in Alpha','Keep the default Sonnet, low effort, adaptive thinking and Alpha project. Run once. Check ALPHA-10, the actual assistant model and the PostToolUse context probe showing lesson10-alpha and a verified cwd.',''),('Compare models carefully','Choose pinned Haiku; the page selects disabled thinking automatically and the host omits effort for that example. Repeat the task. Try Opus with disabled or adaptive thinking. Compare actual IDs, estimates and elapsed times; do not treat this tiny exercise as a benchmark.',''),('Change effort and thinking','Repeat with Sonnet medium effort and disabled thinking. Inspect the actual options. Thinking text remains omitted; returned block counts are metadata, not a window into hidden reasoning. Model/provider support varies.',''),('Switch cwd and add a directory','Choose Beta and enable shared reference. Run a fresh query. Confirm BETA-10, lesson10-beta, verified cwd and SHARED-10 from an actual reference read. The extra directory grants access, not its settings.',''),('Configure a distinct fallback','Choose Sonnet with Opus as backup. Inspect fallbackModel and the model on actual messages. A healthy run usually stays on the primary. No automatic failover is claimed unless actual runtime evidence shows it. Invalid IDs and authentication errors are not a reliable overload exercise.',''),('Run from the terminal and troubleshoot','The sample indexes are 0=Haiku, 1=Sonnet, 2=Opus. sample:env loads .env; sample uses the same shell environment. Keep this terminal open for the server. Ctrl+C stops it. For Windows, configure the real Git Bash path if requested. Another listener needs a different PORT. Provider errors remain actual failures; no saved answers are substituted.',snippet('npm run sample:env -- 1\nnpm run sample:env -- 0\nnpm run sample:env -- 2\nnpm test','powershell'))]
body=''.join(f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{escape(t)}</h2><p>{escape(d)}</p>{c}</section>' for i,(t,d,c) in enumerate(runsteps,1))
document('/run.html','Configure and <em>run the application.</em>','Follow the same task across models, reasoning settings and classroom directories.',body+actions(('/learn.html','← Learning goals'),('/','Open the lab →')))

# Exact source anchors identify each excerpt; display whitespace may differ.
specs=[
 ('Validate the classroom configuration','src/server.ts','const config = validateConfig(input);','const config = validateConfig(input);','Validate the fixed model list, project, supported thinking choices and distinct backup before a query starts.',0,1),
 ('Prepare two projects and shared reference','src/agent.ts','await writeFile(resolve(ROOT, ".runtime", name, file), await readFile(resolve(ROOT, "fixtures", name, file)));','await writeFile(\n  resolve(ROOT, ".runtime", name, file),\n  await readFile(resolve(ROOT, "fixtures", name, file))\n);','Copy trusted fixture bytes into private runtime directories. No browser-supplied project path is accepted.',1,4),
 ('Select primary and optional backup','src/agent.ts','...(config.fallback ? { fallbackModel: config.fallback } : {}),','model: config.model,\n...(config.fallback\n  ? { fallbackModel: config.fallback } : {}),','Use a pinned classroom model and an optional distinct backup. Configuration alone does not prove a fallback happened.',1,2),
 ('Configure effort and thinking separately','src/agent.ts','thinking: config.thinking === "adaptive" ? { type: "adaptive", display: "omitted" } : { type: "disabled" },','...(!config.model.includes("haiku")\n  ? { effort: config.effort } : {}),\nthinking: config.thinking === "adaptive"\n  ? { type: "adaptive", display: "omitted" }\n  : { type: "disabled" },','Keep reasoning effort and thinking configuration independent while respecting the pinned models. This lab does not expose thinking text.',1,2),
 ('Choose cwd and additional directories','src/agent.ts','additionalDirectories: config.shared ? [sharedDirectory()] : [],','cwd: workspace(config.project),\nadditionalDirectories: config.shared\n  ? [sharedDirectory()] : [],','A fresh query selects Alpha or Beta. Enabling the shared directory grants access to its reference file, not its configuration.',1,2),
 ('Preserve and extend the environment','src/agent.ts','LESSON10_CONTEXT: `lesson10-${config.project}`, CLAUDE_AGENT_SDK_CLIENT_APP: "udemy-lesson10/1.0" },','env: {\n  ...process.env,\n  // Private config directory omitted here.\n  LESSON10_CONTEXT: `lesson10-${config.project}`,\n  CLAUDE_AGENT_SDK_CLIENT_APP: "udemy-lesson10/1.0"\n},','TypeScript env replaces subprocess variables, so preserve inherited values before adding a harmless classroom context and app identifier. Raw credentials stay in the process.',1,2),
 ('Start one real SDK query','src/agent.ts','const run = query({ prompt, options });','const run = query({ prompt, options });','Start one query with the fixed task and composed options. The SDK owns model and tool orchestration.',1,2),
 ('Observe the actual assistant model','src/agent.ts','emit({ type: "assistant-model", model: message.message.model });','if (message.type === "assistant") {\n  emit({ type: "assistant-model",\n    model: message.message.model });\n  // Content handling follows.\n}','Read the actual model field on assistant messages instead of relying only on the requested option or the model’s prose.',2,1),
 ('Guard each tool operation','src/agent.ts','if (tool === "Bash") return input.command === PROBE_COMMAND;','if (tool === "Bash")\n  return input.command === PROBE_COMMAND;\n// Read is restricted to selected fixture paths.','The path guard permits only selected reads and one exact Node command. Pre-approval does not replace this application check or create an OS sandbox.',2,3),
 ('Verify actual environment and cwd','src/agent.ts','const evidence = parseProbe(input.tool_response, config);','const evidence = parseProbe(\n  input.tool_response, config\n);\nif (evidence) emit(evidence);','PostToolUse parses the actual command output. The host validates the harmless value and compares the observed cwd with the selected directory; it does not infer either from model prose.',3,1),
 ('Read the optional shared reference','src/agent.ts','if (config.shared) allowed.push(resolve(sharedDirectory(), "reference.md"));','if (config.shared) allowed.push(\n  resolve(sharedDirectory(), "reference.md")\n);','The Read guard permits the shared reference only when the UI enables that experiment. The prompt then requests its actual marker.',3,4),
 ('Preserve cost, time and typed outcome','src/agent.ts','turns: message.num_turns, costUsd: message.total_cost_usd, sessionId: message.session_id, durationMs: Date.now() - started });','turns: message.num_turns,\ncostUsd: message.total_cost_usd,\nsessionId: message.session_id,\ndurationMs: Date.now() - started','Store actual runtime fields and measured elapsed time. A limit or provider failure is not relabelled as success; cost remains an SDK estimate.',2,1),
 ('Render answers and compare observations','src/client.ts','renderMarkdown($("answer"), e.text);','renderMarkdown($("answer"), e.text);','Render model text through the bundled Markdown parser and sanitizer. Keep actual models, probe evidence and comparison rows separate from the answer.',1,0),
]
lanes=['Student UI','Node host','SDK + Claude','Guarded tools','Classroom files'];steps=[];arrows=[]
words=['one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen']
for n,(title,source,anchor,code,explanation,a,b) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');assert anchor in text,(n,anchor)
 anchors=[anchor]+{
  3:['model: config.model,'],
  4:['...(!config.model.includes("haiku") ? { effort: config.effort } : {}),'],
  5:['cwd: workspace(config.project),'],
  6:['env: { ...process.env, CLAUDE_CONFIG_DIR: resolve(ROOT, ".runtime/sdk-home"),'],
  8:['if (message.type === "assistant") {'],
  10:['if (evidence) emit(evidence);'],
 }.get(n,[])
 lines=[text[:text.index(a)].count('\n')+1 for a in anchors]
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=min(lines),lastLine=max(lines),anchors=anchors,sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {words[n-1]}. {explanation} The source label identifies the corresponding application statements.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
